SELECT DISTINCTROW qryaktiveElemente.[Element Nr], qryaktiveElemente.Elektrolyseur, qryaktiveElemente.Generation, qryaktiveElemente.Position, qryaktiveElemente.[Anoden Nr], qryaktiveElemente.[Kathoden Nr], qryaktiveElemente.[Membran Nr], qryaktiveElemente.Membrantyp, qryaktiveElemente.Gruppe, qryaktiveElemente.[Einschalt Datum], qryaktiveElemente.[Ausschalt Datum], qryaktiveElemente.[Ausschalt Datum]-[Einschalt Datum] AS GesamtDOL, IIf(IsNull([Ausschalt Datum]),Date()-[Einschalt Datum],Null) AS AktuelleDOL, qryaktiveElemente.Abschaltgrund, qryaktiveElemente.[Anode Coating], qryaktiveElemente.[Anode Electrode], qryaktiveElemente.[Anode Shell], qryaktiveElemente.[Cathode Coating], qryaktiveElemente.[Cathode Electrode], qryaktiveElemente.[Cathode Shell], qryaktiveElemente.[Info Membrane], qryaktiveElemente.Remarks, qryaktiveElemente.[Montage Datum], qryaktiveElemente.[Demontage Datum], qryaktiveElemente.[Elektroden Abstand]
FROM qryaktiveElemente
WHERE (((qryaktiveElemente.[Anoden Nr]) In (SELECT [Anoden Nr] FROM [qryAktiveElemente] As Tmp GROUP BY [Anoden Nr] HAVING Count(*)>1 )))
ORDER BY qryaktiveElemente.[Anoden Nr];
